import { recipe } from './detail-helpers-v1.js';
export function workflowFor(trade) {
  if(['chartmaker','cartographer','surveyor','translator','scribe','notary','illuminator','bookseller','stationer','map_engraver'].includes(trade.id))return 'documents';
  if(['freight_broker','courier','moneychanger','auctioneer','tutor','healer','stablekeeper','bathkeeper','lamplighter','wellkeeper','undertaker'].includes(trade.id))return 'service';
  if(['food','hospitality','agriculture'].includes(trade.industry) || ['fishmonger','grocer','cheesemonger','perfumer','herbalist','apothecary','soapmaker','alchemist','component_merchant','charcoal_burner','spice_seller','wine_merchant','provisioner'].includes(trade.id))return 'provisions';
  return 'craft';
}
const tasks = {
  documents:'check the names in the record for {product}|compare the draft for {product} against the reference|prepare a clean copy for the {product} order|index the notes for {product}|check the dates in the {product} record|confirm the wording requested for {product}|review corrections to the {product} order|prepare the proof for {product}|trace a missing reference for {product}|check the authorization for {product}',
  service:'confirm an appointment about {product}|check the schedule for {product}|record the customer’s instructions for {product}|verify a receipt for {product}|confirm the scope of the {product} request|prepare the booking record for {product}|check the contact details for {product}|resolve a timing conflict for {product}|copy the agreed terms for {product}|confirm completion of the {product} request',
  provisions:'check the storage record for {product}|weigh the reserved quantity of {product}|prepare a labeled portion of {product}|inspect the containers for {product}|record the source of {product}|check the collection date for {product}|prepare a market sample of {product}|compare two batches of {product}|check the storage conditions for {product}|confirm the customer’s quantity of {product}',
  craft:'compare {product} against the approved pattern|check the finished dimensions of {product}|inspect the surface finish of {product}|prepare a sample of {product}|test the fit of {product}|record the materials used for {product}|check the packing for {product}|prepare the drawing for {product}|compare a replacement with the earlier {product} order|check the maker’s mark on {product}'
};
const requirements='The order belongs to {customer} in {district}.|The reference record stays at {displayName}.|The collection route is {supplyRoute}.|The estimate names {material} as an input.|The order is recorded under {trade} work.|The buyer requests a duplicate record.|The customer must approve any substitution.|The earlier sample must be returned.|The work must match the agreed quantity.|The finished work needs a signed receipt.';
export const workRecipes=Object.fromEntries(Object.entries(tasks).map(([key,values])=>[key,recipe(values.split('|').map(v=>`The current task is to ${v}.`),requirements)]));
// Rumors use the same substantive task as the trade, rather than unrelated generic quests.
const obstacles='before the next market day|using the customer’s recorded instructions|without changing the approved specification|with a written collection record|while keeping the reference sample intact|before the buyer returns to {district}|with receipts for any replacement materials|after checking the previous order|after confirming the supplier’s estimate|with a duplicate for the order ledger';
export const workRumors=Object.fromEntries(Object.entries(tasks).map(([key,values])=>[key,recipe(values,obstacles)]));
